/**
 * CyberDimension Audio Lab — quizzes de fixação e competências desbloqueadas.
 *
 * Cada episódio tem um quiz de 5 questões no padrão do CyberCast (resposta
 * secreta nunca exposta na query pública; gabarito no `correctAnswer`).
 * Completar o episódio desbloqueia uma competência do Career Readiness,
 * mapeada pelo código da série + domínio conceitual.
 */
import { audioLabEpisodes } from "./audioLabEpisodes";
import { AUDIO_LAB_SERIES, getAudioLabSeries } from "./audioLabSeries";
import { ctfQuizBank } from "./audioLab/audioLabCtfQuizzes";

export type AudioLabQuizQuestion = {
  id: string;
  prompt: string;
  options: readonly string[];
  correctAnswer: number;
  explanation: string;
};

export type AudioLabCompetency = {
  code: string;
  label: string;
  area: string;
};

type QuizBankEntry = {
  questions: readonly AudioLabQuizQuestion[];
  competency: AudioLabCompetency;
};

function bank(questions: readonly AudioLabQuizQuestion[], competency: AudioLabCompetency): QuizBankEntry {
  return { questions, competency };
}

function q(id: string, prompt: string, options: readonly string[], correctAnswer: number, explanation: string): AudioLabQuizQuestion {
  return { id, prompt, options, correctAnswer, explanation };
}

export const quizBank: Record<string, QuizBankEntry> = {};

function define(epId: string, entry: QuizBankEntry) {
  quizBank[epId] = entry;
}

// ---------------------------------------------------------------------------
// Security+ em Áudio — securityplus
// ---------------------------------------------------------------------------
define("audio-sec01-identidade-acesso", bank(
  [
    q("audio-sec01-q1", "Qual modelo agrupa permissões em papéis que os usuários herdam?", ["ACL", "RBAC", "MAC", "DAC"], 1, "RBAC (Role-Based Access Control) agrupa permissões em papéis; usuários herdam permissões ao receber um papel, simplificando a gestão em escala."),
    q("audio-sec01-q2", "No princípio do menor privilégio, o usuário recebe:", ["Acesso administrativo padrão", "Apenas o acesso necessário à função", "Todas as permissões de leitura", "Acesso vitalício"], 1, "Menor privilégio concede somente o acesso indispensável à função, reduzindo o dano de contas comprometidas ou erros humanos."),
    q("audio-sec01-q3", "Qual prática reduz o risco após um desligamento?", ["Manter a conta ativa por 90 dias", "Desativar a conta e revisar acessos concedidos", "Aumentar os privilégios", "Compartilhar a senha"], 1, "Desativação imediata e revisão de permissões evitam que credenciais de ex-colaboradores sejam usadas indevidamente."),
    q("audio-sec01-q4", "MFA combina fatores de quais categorias?", ["Dois senhas iguais", "Algo que você sabe, tem e é", "Dois tokens do mesmo tipo", "Senha e lembrete de segurança"], 1, "Autenticação multifator combina fatores independentes: conhecimento (senha), posse (token) e inerência (biometria)."),
    q("audio-sec01-q5", "Uma VPN corporativa com acesso condicional exemplifica:", ["Acesso baseado em contexto", "Acesso irrestrito", "Controle físico", "Criptografia em repouso"], 0, "Acesso condicional avalia contexto (dispositivo, localização, comportamento) antes de liberar o acesso, alinhado ao Zero Trust."),
  ],
  { code: "securityplus-identity", label: "Identidade e Acesso (Security+)", area: "Security Fundamentals" },
));
define("audio-sec02-ameacas-vulnerabilidades", bank(
  [
    q("audio-sec02-q1", "Qual vetor de ataque usa mensagens enganosas direcionadas a um executivo específico?", ["Phishing em massa", "Whaling", "Distribuição de malware", "Força bruta"], 1, "Whaling é o phishing direcionado a figuras de alto escalão; spear-phishing mira indivíduos específicos em geral."),
    q("audio-sec02-q2", "O que diferencia TTP de um IOC?", ["TTP descreve comportamento do atacante", "TTP é sempre um endereço IP", "IOC descreve motivações", "TTP só existe em relatórios anuais"], 0, "TTPs (táticas, técnicas e procedimentos) retratam o comportamento; IOCs são indicadores pontuais como hashes e IPs."),
    q("audio-sec02-q3", "Um exploit desenvolvido para falha desconhecida dos desenvolvedores é chamado de:", ["Patch", "Zero-day", "False positive", "Honeypot"], 1, "Zero-day aproveita vulnerabilidade sem correção disponível; o patch corresponde só sai após a correção ser lançada."),
    q("audio-sec02-q4", "Qual ataque tenta decifrar senhas testando combinações automaticamente?", ["SQL injection", "Ataque de força bruta", "Cross-site scripting", "Man-in-the-middle"], 1, "Força bruta testa muitas combinações de credenciais; bloqueios progressivos e MFA reduzem sua eficácia."),
    q("audio-sec02-q5", "Como a segmentação de rede ajuda na mitigação?", ["Elimina a necessidade de firewall", "Limita o movimento lateral do atacante", "Desativa os logs", "Aumenta a largura de banda"], 1, "Isolar segmentos impede que um atacante com acesso inicial percorra livremente a infraestrutura."),
  ],
  { code: "securityplus-threats", label: "Ameaças e Vulnerabilidades (Security+)", area: "Security Fundamentals" },
));
define("audio-sec03-arquitetura-seguranca", bank(
  [
    q("audio-sec03-q1", "No Zero Trust, qual é o princípio de confiança?", ["Confiar em tudo dentro do perímetro", "Nunca confiar, sempre verificar", "Confiar apenas em dispositivos corporativos", "Confiar apenas após o primeiro login"], 1, "Zero Trust trata cada acesso como potencialmente hostil e exige verificação contínua de identidade, contexto e permissão."),
    q("audio-sec03-q2", "Criptografia em trânsito protege os dados enquanto eles:", ["Estão armazenados em disco", "São transmitidos pela rede", "Estão sendo impressos", "Estão em memória RAM"], 1, "Protocolos como TLS criptografam o tráfego entre sistemas; criptografia em repouso protege dados armazenados."),
    q("audio-sec03-q3", "Qual componente avalia o impacto de uma mudança antes de aplicá-la em produção?", ["Política de backup", "Junta de mudanças (CAB)", "Relatório de inventário", "Plano de testes unitários"], 1, "O Change Advisory Board analisa riscos, janelas e rollback antes de aprovar alterações em ambientes produtivos."),
    q("audio-sec03-q4", "Hashing garante qual propriedade de segurança?", ["Disponibilidade", "Integridade", "Autenticidade de usuário", "Não repúdio de contrato"], 1, "Funções de hash detectam alterações nos dados: qualquer mudança gera um digest diferente, comprovando integridade."),
    q("audio-sec03-q5", "Uma assinatura digital combina:", ["Criptografia simétrica e MAC", "Hash e criptografia assimétrica", "Duas senhas iguais", "Firewall e IDS"], 1, "A assinatura digital aplica hash ao conteúdo e cifra o digest com a chave privada do signatário, garantindo integridade e autenticidade."),
  ],
  { code: "securityplus-architecture", label: "Arquitetura de Segurança (Security+)", area: "Security Fundamentals" },
));
define("audio-sec04-operacoes-seguranca", bank(
  [
    q("audio-sec04-q1", "Qual combinação cria trilha de evidências em sistema crítico?", ["SIEM com logging centralizado", "Post-it na tela do servidor", "Regras de firewall sem registro", "Desligamento programado"], 0, "Logs centralizados com integridade protegida permitem investigação, auditoria e responsabilização de eventos."),
    q("audio-sec04-q2", "Câmeras e catracas em um data center são controles de qual categoria?", ["Gerencial", "Técnico", "Físico", "Preventivo lógico"], 2, "Controles físicos restringem acesso a instalações: cercas, câmeras, biometria de porta e guardas."),
    q("audio-sec04-q3", "Qual exemplo ilustra monitoramento ativo como controle detectivo?", ["Backup semanal", "Regra de correlação de alertas de múltiplas fontes", "Cadeado no rack", "Manual de políticas"], 1, "Correlacionar eventos de fontes diversas permite detectar padrões de ataque que fontes isoladas não revelariam."),
    q("audio-sec04-q4", "Ao escolher um controle, o que deve ser avaliado além do custo?", ["Apenas a marca do equipamento", "Risco, viabilidade e impacto operacional", "Somente a opinião do CEO", "O número de funcionários"], 1, "Seleção de controles equilibra risco residual, custo-benefício, compatibilidade e efeitos sobre o negócio."),
    q("audio-sec04-q5", "Uma empresa decide corrigir a causa de falha após um incidente. Isso ilustra controle de qual tipo?", ["Detectivo", "Corretivo", "Dissuasivo", "Compensatório"], 1, "Corretivos removem efeitos adversos e restauram o estado normal, como restauração de sistemas após incidente."),
  ],
  { code: "securityplus-operations", label: "Operações de Segurança (Security+)", area: "Security Operations" },
));
define("audio-sec05-gestao-programa", bank(
  [
    q("audio-sec05-q1", "Qual princípio do tripé CIA garante que a informação não foi alterada indevidamente?", ["Confidencialidade", "Integridade", "Disponibilidade", "Autenticidade"], 1, "Integridade assegura que os dados permanecem íntegros e inalterados; hashing e assinaturas digitais são exemplos de mecanismos."),
    q("audio-sec05-q2", "O que o modelo AAA descreve na ordem correta?", ["Autenticação, Autorização, Prestação de contas", "Autorização, Autenticação, Auditoria", "Auditoria, Autenticação, Autorização", "Acesso, Autenticação, Auditoria"], 0, "AAA primeiro identifica (autenticação), depois define o que é permitido (autorização) e por fim registra as ações (accountability)."),
    q("audio-sec05-q3", "Compensar um controle ausente significa:", ["Aceitar o risco sem agir", "Implementar salvaguarda alternativa que atende ao mesmo objetivo", "Remover o controle primário", "Ignorar a exigência"], 1, "Controle compensatório atende ao mesmo objetivo de um controle primário ausente ou inviável; a decisão precisa ser documentada e reavaliada."),
    q("audio-sec05-q4", "A defesa em profundidade propõe:", ["Um único controle muito forte", "Controles diferentes, em camadas", "Controles apenas físicos", "Controles apenas gerenciais"], 1, "Camadas de controle fazem com que a falha de uma não entregue o ambiente inteiro ao incidente."),
    q("audio-sec05-q5", "Qual documento formaliza a aceitação de um risco conhecido?", ["Backup schedule", "Risk acceptance register", "Change log", "Network map"], 1, "O registro de aceitação de risco documenta decisão, responsável e prazo de reavaliação, tornando a aceitação auditável."),
  ],
  { code: "securityplus-program", label: "Gestão de Programa (Security+)", area: "Security Program Management" },
));

