for (const [episodeId, entry] of Object.entries(ctfQuizBank)) {
  define(episodeId, entry);
}

export function getAudioLabQuiz(episodeId: string) {
  const entry = quizBank[episodeId];
  return entry ? entry.questions : null;
}

export function getAudioLabCompetency(episodeId: string): AudioLabCompetency | null {
  const entry = quizBank[episodeId];
  return entry ? entry.competency : null;
}

export const AUDIO_LAB_QUIZ_XP_PER_CORRECT = 10;


/** Grades a review-quiz submission against the questions of one episode. */
export function gradeAudioLabQuiz(episodeId: string, answers: number[]) {
  const questions = getAudioLabQuiz(episodeId);
  if (!questions || answers.length !== questions.length) return null;
  const score = questions.reduce((total, question, index) => total + (answers[index] === question.correctAnswer ? 1 : 0), 0);
  return {
    score,
    totalQuestions: questions.length,
    percentage: Math.round((score / questions.length) * 100),
    review: questions.map((question, index) => ({
      id: question.id,
      correct: answers[index] === question.correctAnswer,
      correctAnswer: question.correctAnswer,
      explanation: question.explanation,
    })),
  };
}
